    r[1] = bus_read8(r[1] + 0x2u);
    /* 0x0800D17A: MOV r6, #0x7F */
    r[6] = 0x7Fu;
    cpu_update_nz(r[6]);
    /* 0x0800D17C: ADD r0, r6, #0 */
    cpu_add(&r[0], r[6], 0u, true);
    /* 0x0800D17E: AND r0, r1 */
    r[0] &= r[1]; cpu_update_nz(r[0]);
    /* 0x0800D180: LDRB r2, [r3, #0x6] */
    r[2] = bus_read8(r[3] + 0x6u);
    /* 0x0800D182: MOV r1, #0x80 */
    r[1] = 0x80u;
    cpu_update_nz(r[1]);
    /* 0x0800D184: NEG r1, r1 */
    cpu_sub(&r[1], 0, r[1], true);
    /* 0x0800D186: AND r1, r2 */
    r[1] &= r[2]; cpu_update_nz(r[1]);
    /* 0x0800D188: ORR r1, r0 */
    r[1] |= r[0]; cpu_update_nz(r[1]);
    /* 0x0800D18A: STRB r1, [r3, #0x6] */
    bus_write8(r[3] + 0x6u, r[1]);
    /* 0x0800D18C: LDR r0, [r5, #0x0] */
    r[0] = bus_read32(r[5] + 0x0u);
    /* 0x0800D18E: LDR r2, [pc, #0x4C]  ; =0x0800D1DC */
    r[2] = bus_read32(0x0800D1DCu); /* [0x0800D1DC] */
    /* 0x0800D190: ADD r0, r0, r2 */
    cpu_add(&r[0], r[0], r[2], true);
    /* 0x0800D192: LDRB r0, [r0, #0x0] */
    r[0] = bus_read8(r[0] + 0x0u);
    /* 0x0800D194: LSL r0, r0, #31 */
    r[0] = r[0] << 31;
    cpu_update_nz(r[0]);
    /* 0x0800D196: LSR r0, r0, #31 */
    r[0] = r[0] >> 31;
    cpu_update_nz(r[0]);
    /* 0x0800D198: LSL r0, r0, #7 */
    r[0] = r[0] << 7;
    cpu_update_nz(r[0]);
    /* 0x0800D19A: AND r1, r6 */
    r[1] &= r[6]; cpu_update_nz(r[1]);
