    r[0] = bus_read32(0x0800D1E4u); /* [0x0800D1E4] */
    /* 0x0800D1AC: STR r4, [r0, #0x0] */
    bus_write32(r[0] + 0x0u, r[4]);
    /* 0x0800D1AE: MOV r1, r12 */
    r[1] = r[12];
